function prepareArticleSlot({ scheduledAt, brief, spreadsheetId, sheetName, postStatus }) {
  const date = new Date(scheduledAt);
  if (typeof scheduledAt !== "string" || !Number.isFinite(date.getTime()))
    throw Error("The trigger did not supply a schedule timestamp.");
  if (typeof brief !== "string" || !brief.trim() || brief.length > 4000)
    throw Error("Set an editorial brief up to 4,000 characters.");
  if (
    !/^[A-Za-z0-9_-]{12,}$/.test(spreadsheetId) ||
    spreadsheetId === "YOUR_SPREADSHEET_ID" ||
    typeof sheetName !== "string" ||
    !sheetName.trim() ||
    sheetName.length > 100 ||
    /[\x00-\x1f\x7f]/.test(sheetName)
  ) {
    throw Error("Set the spreadsheet ID and an existing sheet tab.");
  }
  if (!["publish", "draft"].includes(postStatus))
    throw Error("Choose publish or draft for WordPress.");
  const stamp = date.toISOString().slice(0, 16).replace(/\D/g, "");
  return {
    slug: "scheduled-article-" + stamp,
    spreadsheetId,
    sheetName,
    range: "'" + sheetName.replaceAll("'", "''") + "'!A:C",
    postStatus,
    brief: brief.trim(),
    delayMs: Math.max(1, Math.floor(Math.random() * (6 * 60 * 60 * 1000))),
  };
}

function articleResponseRequest({ brief }) {
  const text = { type: "string" };
  const list = { type: "array", items: text };
  const section = {
    type: "object",
    additionalProperties: false,
    required: ["heading", "subheading", "paragraphs", "bullets"],
    properties: { heading: text, subheading: text, paragraphs: list, bullets: list },
  };
  return {
    model: "gpt-6-luna",
    store: false,
    max_output_tokens: 9000,
    instructions:
      "Write a complete article from the editor’s brief. Return plain text in every field. Include a short introduction, three to six factual, useful sections with one or more paragraphs, and a conclusion with practical advice. Use subheadings and bullet lists when useful. Give three to five concrete English image search keywords. Do not invent research, statistics, quotes, links or firsthand claims.",
    input: brief,
    text: {
      format: {
        type: "json_schema",
        name: "scheduled_article",
        strict: true,
        schema: {
          type: "object",
          additionalProperties: false,
          required: ["title", "introduction", "sections", "conclusion", "keywords"],
          properties: {
            title: text,
            introduction: text,
            sections: { type: "array", items: section },
            conclusion: text,
            keywords: list,
          },
        },
      },
    },
  };
}

const settings = {
  brief: "",
  spreadsheetId: "YOUR_SPREADSHEET_ID",
  sheetName: "Sheet1",
  postStatus: "publish",
  siteUrl: "https://wordpress.example.invalid",
};
if (
  !/^https:\/\/[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+(?::[0-9]{1,5})?(?:\/[A-Za-z0-9_-]+)*$/.test(
    settings.siteUrl,
  ) ||
  settings.siteUrl.includes(".invalid")
)
  throw Error("Set a trusted HTTPS WordPress site URL without a trailing slash.");
const slot = prepareArticleSlot({ scheduledAt: $input.first().json.timestamp, ...settings });
return [
  {
    json: {
      slot,
      siteUrl: settings.siteUrl,
      delayMs: slot.delayMs,
      request: articleResponseRequest(slot),
    },
  },
];

function structuredDraftReply(reply) {
  const messages = reply?.output?.filter((x) => x?.type === "message");
  const contents = messages?.[0]?.content;
  if (
    reply?.status !== "completed" ||
    messages?.length !== 1 ||
    messages[0].role !== "assistant" ||
    messages[0].status !== "completed" ||
    contents?.length !== 1 ||
    contents[0].type !== "output_text"
  ) {
    throw Error("OpenAI did not complete the article request");
  }
  return JSON.parse(contents[0].text);
}

function escapeDraftHtml(value) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function renderScheduledArticle(article, escape) {
  function text(input, max, empty = false) {
    if (
      typeof input !== "string" ||
      (!empty && !input.trim()) ||
      input.length > max ||
      /[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(input)
    )
      throw Error("The model did not return a complete article.");
    return input.trim();
  }
  const title = text(article?.title, 240);
  if (/[<>\r\n]/.test(title)) throw Error("The article title must be plain text.");
  if (
    !Array.isArray(article.sections) ||
    article.sections.length < 3 ||
    article.sections.length > 6 ||
    !Array.isArray(article.keywords) ||
    article.keywords.length < 3 ||
    article.keywords.length > 5
  ) {
    throw Error("The article needs three to six sections and three to five image keywords.");
  }
  const keywords = article.keywords.map((keyword) => text(keyword, 28));
  if (keywords.some((keyword) => !/^[A-Za-z0-9][A-Za-z0-9 -]*$/.test(keyword)))
    throw Error("Image keywords must be plain English search terms.");
  const paragraph = (value) => "<p>" + escape(text(value, 3600)) + "</p>";
  const sections = article.sections
    .map((section) => {
      if (
        !Array.isArray(section.paragraphs) ||
        !section.paragraphs.length ||
        section.paragraphs.length > 5 ||
        !Array.isArray(section.bullets) ||
        section.bullets.length > 8
      )
        throw Error("The article has an incomplete section.");
      const heading = "<h2>" + escape(text(section.heading, 150)) + "</h2>";
      const subheading = text(section.subheading, 150, true);
      const bullets = section.bullets
        .map((bullet) => "<li>" + escape(text(bullet, 500)) + "</li>")
        .join("");
      return (
        heading +
        (subheading ? "<h3>" + escape(subheading) + "</h3>" : "") +
        section.paragraphs.map(paragraph).join("") +
        (bullets ? "<ul>" + bullets + "</ul>" : "")
      );
    })
    .join("\n");
  const content =
    "<h1>" +
    escape(title) +
    "</h1>" +
    paragraph(article.introduction) +
    "\n" +
    sections +
    "\n<h2>Conclusion</h2>" +
    paragraph(article.conclusion);
  if (content.length > 45000)
    throw Error("The rendered article exceeds the sheet cell size budget.");
  return { title, content, query: keywords.join(" "), logKeywords: keywords.join("+") };
}

const { slot, siteUrl } = $("Set brief and destinations").first().json;
const article = renderScheduledArticle(
  structuredDraftReply($input.first().json.body),
  escapeDraftHtml,
);
const sheetUrl =
  "https://sheets.googleapis.com/v4/spreadsheets/" +
  slot.spreadsheetId +
  "/values/" +
  encodeURIComponent(slot.range) +
  ":append?valueInputOption=RAW&insertDataOption=INSERT_ROWS";
return [
  {
    json: {
      slot,
      siteUrl,
      article,
      sheetUrl,
      log: {
        majorDimension: "ROWS",
        values: [[article.title, article.content, article.logKeywords]],
      },
    },
  },
];

return Object.keys($input.first().json).length
  ? []
  : [{ json: $("Prepare article and search terms").first().json, pairedItem: { item: 0 } }];

function confirmedArticleRow(reply, slot) {
  const range =
    typeof reply?.updatedRange === "string" && reply.updatedRange.match(/^(.*)!A([1-9]\d*):C\2$/);
  const tab = range && range[1].replace(/^'(.*)'$/, "$1").replaceAll("''", "'");
  if (
    reply?.spreadsheetId !== slot.spreadsheetId ||
    reply.updatedRows !== 1 ||
    reply.updatedColumns !== 3 ||
    reply.updatedCells !== 3 ||
    tab !== slot.sheetName
  )
    throw Error(
      "Google Sheets did not confirm the expected article row. Check the log before recovery.",
    );
  return reply.updatedRange;
}

const job = $("Prepare article and search terms").first().json;
const body = $input.first().json.body;
const sheetRange = confirmedArticleRow(
  { ...body.updates, spreadsheetId: body.spreadsheetId },
  job.slot,
);
return [{ json: { ...job, sheetRange } }];

function escapeDraftHtml(value) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function articlePost(article, slot, photos, escape) {
  const photo = Array.isArray(photos) && photos[0];
  if (
    !photo ||
    !Number.isSafeInteger(photo.id) ||
    photo.id < 1 ||
    typeof photo.photographer !== "string" ||
    !photo.photographer.trim() ||
    photo.photographer.length > 160 ||
    typeof photo.url !== "string" ||
    typeof photo.src?.landscape !== "string" ||
    !new RegExp("^https://www\\.pexels\\.com/photo/(?:[A-Za-z0-9-]+-)?" + photo.id + "/?$").test(
      photo.url,
    ) ||
    !new RegExp(
      "^https://images\\.pexels\\.com/photos/" + photo.id + "/[A-Za-z0-9_.-]+(?:\\?[^\\s<>\"']+)?$",
    ).test(photo.src.landscape)
  ) {
    throw Error("Pexels did not return a usable landscape photo with matching image and credit.");
  }
  const alt =
    typeof photo.alt === "string" && photo.alt.trim()
      ? photo.alt.slice(0, 300)
      : "Photo by " + photo.photographer;
  const media =
    '<figure><img src="' +
    escape(photo.src.landscape) +
    '" alt="' +
    escape(alt) +
    '">' +
    '<figcaption><a href="' +
    escape(photo.url) +
    '">Photo by ' +
    escape(photo.photographer) +
    " on Pexels</a></figcaption></figure>";
  return {
    title: article.title,
    content: media + "\n" + article.content,
    slug: slot.slug,
    status: slot.postStatus,
  };
}

const { article, slot, siteUrl, sheetRange } = $("Confirm the Google Sheets row").first().json;
const post = articlePost(article, slot, $input.first().json.body.photos, escapeDraftHtml);
return [{ json: { post, slot, sheetRange, url: siteUrl + "/wp-json/wp/v2/posts" } }];

function confirmedArticlePost(post, slot) {
  if (
    !Number.isSafeInteger(post?.id) ||
    post.id < 1 ||
    post.slug !== slot.slug ||
    post.status !== slot.postStatus
  ) {
    throw Error("WordPress did not confirm the expected post. Check its slug before recovery.");
  }
  return { postId: post.id, slug: post.slug, status: post.status };
}

const { slot, sheetRange } = $("Add the photo and credit").first().json;
const receipt = confirmedArticlePost($input.first().json.body, slot);
return [{ json: { ...receipt, sheetRange } }];
